(()=>{const s=document.currentScript?.closest('[data-barba="container"]')||document,c=window.matchMedia("(prefers-reduced-motion: reduce)").matches,n=[...s.querySelectorAll("[data-telop]")].filter(t=>/^\d+$/.test(t.dataset.telop.trim()));if(!n.length||c||!("IntersectionObserver"in window))return;const i=t=>{const e=parseInt(t.dataset.telop,10),d=900,l=performance.now(),o=u=>{const a=Math.min((u-l)/d,1);t.textContent=Math.round(e*(1-Math.pow(1-a,3))),a<1&&requestAnimationFrame(o)};requestAnimationFrame(o)},r=new IntersectionObserver(t=>{t.forEach(e=>{e.isIntersecting&&(r.unobserve(e.target),i(e.target))})},{threshold:.6});n.forEach(t=>{t.textContent="0",r.observe(t)})})();
